'use strict';
/* Literary Edition: original V2 book form, ISBN and camera retained. */
const LKEY='ma-bibliotheque-literary-v1';
const extrasDefault=()=>({journal:[],loans:[],goal:12,seriesCatalog:{}});
const layoutDefault=()=>({finish:'walnut',lights:true,cabinets:1,positions:{},decorations:{},decorSides:{},auto:false,order:'authors'});
let state,storageBlocked=false;
function validateBackup(d){
 if(!d||typeof d!=='object'||![1,2,3].includes(d.version)||!Array.isArray(d.books))throw Error('Format V1/V2/Literary non reconnu');
 if(d.books.length>32000)throw Error('Trop de livres');
 const ids=new Set();for(const b of d.books){if(!b||typeof b!=='object'||typeof b.id!=='string'||!b.id||['__proto__','constructor','prototype'].includes(b.id)||typeof b.title!=='string'||typeof b.authors!=='string')throw Error('Fiche livre invalide');if(ids.has(b.id))throw Error('Identifiants de livres dupliqués');ids.add(b.id);for(const k of ['progress','pages','rating','price'])if(b[k]!==''&&b[k]!=null&&(!Number.isFinite(Number(b[k]))||Number(b[k])<0))throw Error('Valeur numérique invalide : '+k);if(Number(b.rating)>5)throw Error('Note supérieure à 5');if(b.cover&&!/^(https?:\/\/|data:image\/(png|jpeg|webp);base64,)/i.test(b.cover))throw Error('URL de couverture non autorisée');}
 const v=d.v2||extrasDefault();if(typeof v!=='object'||Array.isArray(v))throw Error('Données de suivi invalides');for(const k of ['journal','loans'])if(v[k]!=null&&(!Array.isArray(v[k])||v[k].some(e=>!e||typeof e.id!=='string'||typeof e.book!=='string'||typeof e.date!=='string')))throw Error('Format '+k+' invalide');
 if(v.goal!=null&&(!Number.isInteger(Number(v.goal))||Number(v.goal)<1||Number(v.goal)>10000))throw Error('Objectif invalide');if(v.seriesCatalog!=null&&(typeof v.seriesCatalog!=='object'||Array.isArray(v.seriesCatalog)))throw Error('Catalogue de séries invalide');
 for(const b of d.books)for(const k of ['originalTitle','authors','isbn','genre','tags','language','kind','format','publisher','published','series','volume','cover','ownership','reading','review','started','finished','acquired','location','created'])if(b[k]!=null&&typeof b[k]!=='string')throw Error('Métadonnée invalide : '+k);
 for(const b of d.books)for(const k of ['progress','pages'])if(b[k]!==''&&b[k]!=null&&!Number.isInteger(Number(b[k])))throw Error('Pages non entières');
 for(const e of v.journal||[])if(!Number.isFinite(Number(e.pages))||Number(e.pages)<0||typeof e.note!=='string')throw Error('Séance invalide');
 for(const e of v.loans||[])if(typeof e.person!=='string'||(e.due!=null&&typeof e.due!=='string')||(e.returned!=null&&typeof e.returned!=='boolean'))throw Error('Prêt invalide');
 for(const [name,c] of Object.entries(v.seriesCatalog||{}))if(!c||!Number.isInteger(Number(c.total))||Number(c.total)<1||Number(c.total)>1000)throw Error('Total de série invalide');
 const books=d.books.map(b=>({...blank(),...b}));
 if(d.literary!=null&&(typeof d.literary!=='object'||Array.isArray(d.literary)))throw Error('Préférences invalides');if(d.literary?.trash!=null&&(!Array.isArray(d.literary.trash)||d.literary.trash.length>100||d.literary.trash.some(e=>!e||!e.book||typeof e.book.id!=='string'||typeof e.book.title!=='string'||typeof e.book.authors!=='string')))throw Error('Corbeille invalide');
 const l={...layoutDefault(),...(d.literary?.layout||{})};if(!l.positions||typeof l.positions!=='object'||Array.isArray(l.positions))throw Error('Positions invalides');if(!l.decorSides||typeof l.decorSides!=='object'||Array.isArray(l.decorSides))l.decorSides={};if(!l.decorations||typeof l.decorations!=='object')throw Error('Décorations invalides');for(const value of Object.values(l.decorations))if(!['','plant','globe','lantern','frame'].includes(value))throw Error('Décoration invalide');l.finish=['walnut','oak','mahogany'].includes(l.finish)?l.finish:'walnut';l.cabinets=Math.max(1,Math.min(1000,Number(l.cabinets)||1));
 return {...d,version:3,books,v2:{...extrasDefault(),...v},literary:{theme:'auto',...(d.literary||{}),layout:l}};
}
try{const raw=localStorage.getItem(LKEY);const legacyRaw=localStorage.getItem(KEY),extraRaw=localStorage.getItem(V2KEY);state=validateBackup(raw?JSON.parse(raw):{...(legacyRaw?JSON.parse(legacyRaw):db),v2:extraRaw?JSON.parse(extraRaw):extrasDefault(),literary:{theme:['light','dark'].includes(localStorage.getItem(THEME))?localStorage.getItem(THEME):'auto',layout:layoutDefault()}});if(!raw&&localStorage.getItem(KEY)){localStorage.setItem('ma-bibliotheque-pre-literary-backup',JSON.stringify({booksRaw:localStorage.getItem(KEY),extrasRaw:localStorage.getItem(V2KEY),uiRaw:localStorage.getItem(UIKEY),themeRaw:localStorage.getItem(THEME)}));}if(!raw)localStorage.setItem(LKEY,JSON.stringify(state));db={version:1,books:state.books};}catch(e){storageBlocked=true;state={version:3,books:[],v2:extrasDefault(),literary:{theme:'auto',layout:layoutDefault()}};db={version:1,books:[]};alert('Lecture ou migration interrompue : '+e.message+'. Les données sources restent intactes. Exportez les données brutes depuis Données et sauvegardes.');}
function commit(candidate){if(storageBlocked){alert('Écriture bloquée pour protéger les données illisibles. Exportez les données brutes puis restaurez une sauvegarde valide.');return false}try{const clean=validateBackup(candidate);localStorage.setItem(LKEY,JSON.stringify(clean));state=clean;db={version:1,books:state.books};return true}catch(e){alert('Enregistrement refusé : '+e.message+'. Les données précédentes sont conservées.');return false}}
saveCandidate=function(candidate){const remaining=new Set(candidate.books.map(b=>b.id)),removed=db.books.filter(b=>!remaining.has(b.id));return commit({...state,books:candidate.books,literary:{...state.literary,trash:[...(state.literary.trash||[]),...removed.map(book=>({book,deleted:today()}))].slice(-100)}})};
readV2=function(){return structuredClone(state.v2)};
saveV2=function(x){return commit({...state,v2:x})};
function saveLayout(l){return commit({...state,literary:{...state.literary,layout:l}})}
function ownedBooks(){return db.books.filter(b=>['owned','lent'].includes(b.ownership))}
function snapshot(){return {...state,exportedAt:new Date().toISOString(),ui:{viewMode,sortMode,sortDirection,query,filterLanguage,filterGenre,filterStatus,filterKind,filterFormat,filterSeries,filterRating}}}
function exportJSON(prefix='ma-bibliotheque-literary'){download(JSON.stringify(snapshot(),null,2),prefix+'-'+today()+'.json','application/json')}
const palette=['#94562e','#d19955','#8f7469','#6c4c39','#cdb48d','#b87652','#4b3526','#91734c'];
const iconPaths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',collection:'M4 3h6v18H4zM13 3h6v18h-6zM7 7v3m9-3v3',shelf:'M3 3h18v18H3zM3 10h18M3 17h18M7 4v5m4-5v5m5-5v5M7 11v5m5-5v5',reading:'M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2zM12 6v15',more:'M4 12h.1m7.9 0h.1m7.9 0h.1'};
function ico(k){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[k]||iconPaths.collection}"/></svg>`}
$('#nav').innerHTML=[['home','Accueil'],['collection','Livres'],['shelf','Bibliothèque'],['reading','Lectures'],['more','Plus']].map(([k,n])=>`<button data-page="${k}">${ico(k)}${n}</button>`).join('');
$('#theme').onclick=()=>settingsModal();
$('#add').onclick=()=>form();
$('.eyebrow').textContent='LITERARY EDITION';
let sectionTitle='',subset=null,scannerSelection=false;
setPage=function(p){if(!['home','collection','shelf','reading','more','series','stats','goals','wishlist','acquisitions','loans','organization','data','settings'].includes(p))p='home';page=p;subset=null;closeModal();render();window.scrollTo(0,0);try{sessionStorage.setItem('literary-page',p)}catch{}};
function applyTheme(){let t=state.literary.theme;document.body.classList.toggle('light',t==='light'||(t==='auto'&&matchMedia('(prefers-color-scheme: light)').matches));document.querySelector('meta[name="theme-color"]').content=document.body.classList.contains('light')?'#fbf2e9':'#181310'}
matchMedia('(prefers-color-scheme: light)').addEventListener('change',applyTheme);
cover=function(b){return b.cover?`<img src="${esc(b.cover)}" alt="Couverture de ${esc(b.title)}" loading="lazy" onerror="this.outerHTML='<span class=&quot;fallback&quot;>Couverture indisponible</span>'">`:`<span class="fallback">${esc(b.title||'Sans titre')}</span>`};
card=function(b){return `<article class="book" data-detail="${esc(b.id)}" tabindex="0" role="button" aria-label="Ouvrir ${esc(b.title)}"><div class="cover">${cover(b)}</div><div class="bookinfo"><strong>${esc(b.title)}</strong><small>${esc(b.authors||'Auteur inconnu')}</small><span class="pill">${b.ownership==='wish'?'Souhait':status(b.reading)}</span>${b.favorite?' <span aria-label="Favori">♥</span>':''}${readingProgress(b)}</div></article>`};
const empty=t=>`<div class="empty">${t}</div>`;
const group=(arr,key)=>{const m={};arr.forEach(b=>{String(b[key]||'Non renseigné').split(key==='genre'?',':'\u0000').forEach(x=>{x=x.trim()||'Non renseigné';m[x]=(m[x]||0)+1})});return Object.entries(m).sort((a,b)=>b[1]-a[1])};
function metrics(){const a=ownedBooks(),done=a.filter(b=>b.reading==='done'),series=new Set(a.map(b=>b.series).filter(Boolean)),authors=new Set(a.flatMap(b=>b.authors.split(',').map(s=>s.trim()).filter(Boolean)));return {a,done,series,authors}}
function readingRow(b){const pct=Number(b.pages)>0?Math.min(100,Math.round(100*Number(b.progress||0)/Number(b.pages))):0;return `<div class="box section progressrow"><div class="cover" data-detail="${esc(b.id)}" role="button" tabindex="0">${cover(b)}</div><div><h3>${esc(b.title)}</h3><small>${esc(b.authors)}</small><div class="bar"><span style="width:${pct}%"></span></div><div class="row"><small>${esc(b.progress||0)} / ${esc(b.pages||'—')} pages · ${pct}%</small><button class="btn" data-detail="${esc(b.id)}">Ouvrir</button></div></div></div>`}
function goalCard(){const y=new Date().getFullYear(),n=ownedBooks().filter(b=>b.reading==='done'&&b.finished.startsWith(y+'')).length,g=state.v2.goals?.[y]||state.v2.goal;return `<section class="box section"><div class="row"><h3>Objectif ${y}</h3><button class="btn" data-action="goal">Modifier</button></div><p>${n} / ${g} livres terminés</p><div class="bar"><span style="width:${Math.min(100,n/g*100)}%"></span></div><small>Seules les lectures avec une date de fin comptent.</small></section>`}
function donut(title,items,key){const total=items.reduce((s,x)=>s+x[1],0);let n=0;const bg=items.map((x,i)=>{const from=n;n+=total?x[1]/total*100:0;return `${palette[i%palette.length]} ${from}% ${n}%`}).join(',');return `<section class="box section"><h3>${esc(title)}</h3>${total?`<div class="donutrow"><div class="donut" data-total="${total}" style="background:conic-gradient(${bg})" role="img" aria-label="${esc(items.map(x=>x.join(': ')).join(', '))}"></div><div class="legend">${items.map(([k,v],i)=>`<button data-chart-key="${key}" data-chart-value="${esc(k)}"><span><i style="background:${palette[i%palette.length]}"></i>${esc(key==='reading'?status(k):key==='language'?lang(k):k)}</span><b>${v}</b></button>`).join('')}</div></div>`:empty('Aucune donnée enregistrée.')}</section>`}
function bars(title,items,key){const max=Math.max(1,...items.map(x=>x[1]));return `<section class="box section"><h3>${esc(title)}</h3>${items.length?items.map(([k,v])=>`<div class="chartbar"><span>${esc(k)}</span><button data-chart-key="${key}" data-chart-value="${esc(k)}" aria-label="${esc(k)} : ${v}" title="${esc(k)} : ${v}"><span style="width:${100*v/max}%"></span></button><b>${v}</b></div>`).join(''):empty('Aucune donnée datée.')}</section>`}
function collectionPage(){return `<div class="searchline"><input id="literary-search" value="${esc(query)}" placeholder="Rechercher un livre…" aria-label="Rechercher un livre"><button class="btn" data-action="filters" aria-label="Filtres avancés">☷ Filtres</button></div><div class="sortline"><select id="literary-sort" aria-label="Trier">${[['recent','Ajouts récents'],['title','Titre'],['authors','Auteur'],['published','Publication'],['rating','Note'],['pages','Pages'],['progress','Progression']].map(([v,t])=>`<option value="${v}" ${sortMode===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn" data-action="direction" aria-label="Inverser le tri">${sortDirection==='desc'?'↓':'↑'}</button><button class="btn" data-action="view" aria-label="Changer la présentation">${viewMode==='grid'?'☷':'▦'}</button></div><p class="filtercount" id="literary-count"></p><div class="books ${viewMode==='list'?'list-view':''}" id="literary-results"></div>`}
function filtered(){let a=(page==='wishlist'?db.books.filter(b=>b.ownership==='wish'):ownedBooks());if(subset)a=a.filter(subset);a=a.filter(b=>(!query||norm([b.title,b.originalTitle,b.authors,b.isbn,b.series,b.tags,b.publisher].join(' ')).includes(norm(query)))&&(!filterLanguage||b.language===filterLanguage)&&(!filterGenre||(b.genre||'Non renseigné').split(',').map(s=>s.trim()).includes(filterGenre))&&(!filterStatus||b.reading===filterStatus)&&(!filterKind||b.kind===filterKind)&&(!filterFormat||b.format===filterFormat)&&(!filterSeries||b.series===filterSeries)&&(!filterRating||Number(b.rating)>=Number(filterRating))&&(!state.literary.favoriteOnly||b.favorite));const idx=new Map(db.books.map((b,i)=>[b.id,i]));a.sort((a,b)=>{let x=a[sortMode],y=b[sortMode];if(sortMode==='recent'){x=a.created||'';y=b.created||''}if(sortMode==='progress'){x=Number(a.pages)>0?Number(a.progress)/a.pages:0;y=Number(b.pages)>0?Number(b.progress)/b.pages:0}let d=['rating','pages','progress'].includes(sortMode)?Number(x||0)-Number(y||0):collator.compare(String(x||''),String(y||''));if(!d)d=idx.get(a.id)-idx.get(b.id);return sortDirection==='desc'?-d:d});return a}
function paintResults(){const t=$('#literary-results');if(!t)return;const a=filtered();t.innerHTML=a.length?a.map(card).join(''):empty('Aucun livre ne correspond. Ajoute un livre ou ajuste tes filtres.');$('#literary-count').textContent=a.length+' livre(s) · '+[filterLanguage,filterGenre,filterStatus,filterKind,filterFormat,filterSeries,filterRating,state.literary.favoriteOnly].filter(Boolean).length+' filtre(s) actif(s)'}
render=function(){applyTheme();const {a,done,series,authors}=metrics();const titles={home:'Ma Bibliothèque',collection:'Mes livres',shelf:'Bibliothèque virtuelle',reading:'Mes lectures',more:'Plus',series:'Séries et auteurs',stats:'Statistiques',goals:'Suivi et objectifs',wishlist:'Liste de souhaits',acquisitions:'Acquisitions',loans:'Prêts',organization:'Collections et organisation',data:'Données et sauvegardes',settings:'Paramètres'};$('#heading').textContent=titles[page]||'Ma Bibliothèque';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(!['home','collection','shelf','reading','more'].includes(page)&&b.dataset.page==='more')));let h='';
 if(page==='home'){h=`<section class="hero"><small>LE PLAISIR DE COLLECTIONNER</small><h2>Bienvenue chez toi.</h2><p>Les histoires que tu gardes.<br>Celles qu’il te reste à découvrir.</p><button class="btn primary" data-go="shelf">Ouvrir ma bibliothèque →</button></section><div class="stats">${[['Livres',a.length],['Séries',series.size],['Auteurs',authors.size],['Terminés',done.length]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="homecolumns"><div><div class="row section"><h2>Lectures en cours</h2><button class="btn" data-go="reading">Tout voir</button></div>${a.filter(b=>b.reading==='reading').map(readingRow).join('')||empty('Aucune lecture en cours. Ouvre une fiche pour commencer.')}<section class="section"><h2>Derniers ajouts</h2><div class="books">${a.slice().sort((x,y)=>collator.compare(y.created,x.created)||db.books.indexOf(y)-db.books.indexOf(x)).slice(0,6).map(card).join('')||empty('Ta collection attend son premier livre.')}</div></section></div><div>${donut('Mes lectures',group(a,'reading'),'reading')}<div class="stats">${[['À lire',a.filter(b=>b.reading==='unread').length],['En cours',a.filter(b=>b.reading==='reading').length]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>${goalCard()}<button class="btn" data-action="add">＋ Ajouter un livre</button> <button class="btn" data-go="data">Sauvegardes</button></div></div>`}
 if(page==='collection'||page==='wishlist')h=collectionPage();
 if(page==='more')h=`<p class="muted">Ta collection, dans tous ses détails.</p><div class="tiles">${[['series','Séries et auteurs','Les œuvres et leurs créateurs','▥'],['stats','Statistiques','Explorer ta collection','◔'],['goals','Suivi et objectifs','Journal et objectif annuel','◷'],['wishlist','Liste de souhaits','Tes prochaines découvertes','♡'],['acquisitions','Acquisitions','Dates et achats','＋'],['loans','Prêts','Livres confiés et retours','⇄'],['organization','Collections et organisation','Emplacements et éditions','▤'],['data','Données et sauvegardes','Exporter et restaurer','↧'],['settings','Paramètres et personnalisation','Thèmes et ambiance','☼']].map(([p,t,s,i])=>`<button class="tile" data-go="${p}"><span>${i}</span><b>${t}</b><small>${s}</small></button>`).join('')}</div>`;
 if(page==='reading'){h=`${goalCard()}<h2>En cours</h2>${a.filter(b=>b.reading==='reading').map(readingRow).join('')||empty('Aucune lecture en cours.')}<h2>Historique des lectures terminées</h2>${done.slice().sort((x,y)=>collator.compare(y.finished,x.finished)).map(b=>`<div class="box section"><div class="row"><div><b>${esc(b.title)}</b><p><small>${esc(b.authors)}<br>${esc(b.started||'Début non renseigné')} → ${esc(b.finished||'Fin non renseignée')}</small></p></div><button class="btn" data-detail="${esc(b.id)}">Ouvrir</button></div></div>`).join('')||empty('Aucune lecture terminée.')}`}
 if(page==='stats'){const monthly={},yearly={},acquired={};done.forEach(b=>{if(b.finished){const m=b.finished.slice(0,7),y=b.finished.slice(0,4);monthly[m]=(monthly[m]||0)+1;yearly[y]=(yearly[y]||0)+1}});a.forEach(b=>{const d=b.acquired||b.created;if(d)acquired[d.slice(0,7)]=(acquired[d.slice(0,7)]||0)+1});let sum=0;const growth=Object.entries(acquired).sort().map(([k,v])=>[k,sum+=v]);const ratings=a.filter(b=>Number(b.rating)>0);h=`<div class="stats">${[['Éditions possédées',a.length],['Œuvres',new Set(a.map(b=>b.workId||norm(b.title)+'|'+norm(b.authors))).size],['Note moyenne',ratings.length?(ratings.reduce((s,b)=>s+Number(b.rating),0)/ratings.length).toFixed(1):'—'],['Séries',series.size]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="note">Touche une légende ou une barre pour voir les livres concernés. Les genres multiples sont comptés séparément. L’évolution reflète les livres actuellement conservés, selon leur acquisition ou leur ajout.</p><div class="chartgrid">${donut('Statuts de lecture',group(a,'reading'),'reading')}${donut('Romans et BD · types',group(a,'kind'),'kind')}${donut('Langues',group(a,'language'),'language')}${bars('Genres',group(a,'genre'),'genre')}${bars('Terminés par mois',Object.entries(monthly).sort(),'finishedMonth')}${bars('Terminés par année',Object.entries(yearly).sort(),'finishedYear')}${bars('Évolution de la collection',growth,'growth')}${bars('Notes et évaluations',group(ratings,'rating'),'rating')}${bars('Éditions par série',group(a.filter(b=>b.series),'series'),'series')}</div>${goalCard()}`}
 if(page==='goals')h=`${goalCard()}<div class="row section"><h2>Journal de lecture</h2><button class="btn primary" data-action="session">＋ Séance</button></div>${state.v2.journal.slice().sort((x,y)=>collator.compare(y.date,x.date)).map(e=>`<div class="box section"><div class="row"><b>${esc(db.books.find(b=>b.id===e.book)?.title||'Livre supprimé')}</b><button class="btn" data-del-session="${esc(e.id)}">Supprimer</button></div><p><small>${esc(e.date)} · ${esc(e.pages)} pages</small></p><p>${esc(e.note)}</p></div>`).join('')||empty('Aucune séance enregistrée.')}`;
 if(page==='loans')h=`<div class="row section"><p class="muted">${state.v2.loans.filter(l=>!l.returned).length} prêt(s) actif(s)</p><button class="btn primary" data-action="loan">＋ Prêt</button></div>${state.v2.loans.map(l=>`<div class="box section"><b>${esc(db.books.find(b=>b.id===l.book)?.title||'Livre supprimé')}</b><p>${esc(l.person)}</p><small>${esc(l.date)}${l.due?' · retour prévu '+esc(l.due):''}</small><div class="actions"><button class="btn" data-loan-return="${esc(l.id)}">${l.returned?'Rendu · annuler le retour':'Marquer rendu'}</button><button class="btn" data-loan-delete="${esc(l.id)}">Supprimer</button></div></div>`).join('')||empty('Aucun prêt enregistré.')}`;
 if(page==='series')h=seriesPage();
 if(page==='shelf')h=shelfPage();
 if(page==='acquisitions'){const dated=a.filter(b=>b.acquired).sort((x,y)=>collator.compare(y.acquired,x.acquired));h=`<p class="note">${dated.length} acquisition(s) datée(s) · Total des prix renseignés : ${a.reduce((s,b)=>s+(Number(b.price)||0),0).toLocaleString('fr-FR',{style:'currency',currency:'EUR'})}. Renseigne date et prix dans chaque fiche.</p>${dated.map(b=>`<div class="box section row"><div><b>${esc(b.title)}</b><p><small>${esc(b.acquired)} · ${esc(b.price||'—')} €</small></p></div><button class="btn" data-detail="${esc(b.id)}">Ouvrir</button></div>`).join('')||empty('Aucune acquisition datée.')}<h2>Dates à compléter</h2><div class="books">${a.filter(b=>!b.acquired).map(card).join('')}</div>`}
 if(page==='organization')h=`<div class="box section"><h2>Emplacements et collections</h2><p class="note">Utilise les champs Emplacement et Tags des fiches pour organiser les livres. Les éditions d’une même œuvre peuvent partager un identifiant d’œuvre ; elles restent des exemplaires distincts.</p><button class="btn" data-go="shelf">Organiser le meuble</button></div>${group(a,'location').map(([k,v])=>`<button class="tile section" data-location="${esc(k)}"><b>${esc(k)}</b><small>${v} livre(s)</small></button>`).join('')||empty('Aucun livre enregistré.')}`;
 if(page==='data')h=dataPage();
 if(page==='settings')h=`<div class="box section"><h2>Apparence</h2><label class="field">Thème<select id="theme-select">${[['auto','Automatique'],['light','Clair · parchemin'],['dark','Sombre · chocolat']].map(([v,t])=>`<option value="${v}" ${state.literary.theme===v?'selected':''}>${t}</option>`).join('')}</select></label></div><button class="tile" data-action="cabinet-settings"><b>Personnaliser le meuble</b><small>Finition, éclairage et décorations</small></button><p class="note">Literary Edition · application indépendante · données locales.<br>Internet est nécessaire pour les recherches ISBN et les couvertures non encore mises en cache.</p><p class="note" id="offline-detail">${navigator.onLine?'Connecté':'Hors connexion'} · ${swStatus}</p>`;
 const secondary=!['home','collection','shelf','reading','more'].includes(page);$('#app').innerHTML=(secondary?'<button class="btn subback" data-go="more">← Plus</button>':'')+h;if(page==='collection'||page==='wishlist')paintResults();if(page==='shelf')bindShelf();};
function modal(title,html){closeModal();$('#overlay').innerHTML=`<div class="modalwrap"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${esc(title)}</h2><button class="btn" data-action="close" aria-label="Fermer">✕</button></div>${html}</div></div>`;setTimeout(()=>$('#overlay button, #overlay input')?.focus(),0)}
function detail(id){const b=db.books.find(x=>x.id===id);if(!b)return;const editions=db.books.filter(x=>x.id!==id&&(b.workId?x.workId===b.workId:norm(x.title)===norm(b.title)&&norm(x.authors)===norm(b.authors)));modal(b.title,`<div class="detailhead"><div class="cover">${cover(b)}</div><div><span class="badge">${esc(b.kind)} · ${esc(lang(b.language))}</span><h2>${esc(b.title)}</h2><p>${esc(b.authors)}</p><p>${b.rating?'★ '+esc(b.rating)+'/5':'Non noté'}</p><span class="badge">${status(b.reading)}</span></div></div><div class="detailinfo">${[['Série',b.series||'—'],['Tome',b.volume||'—'],['Éditeur',b.publisher||'—'],['Édition / support',b.format],['ISBN',b.isbn||'—'],['Collection',b.ownership==='wish'?'Souhaité':b.ownership==='lent'?'Prêté':b.ownership==='sold'?'Vendu':'Possédé'],['Début',b.started||'—'],['Fin',b.finished||'—'],['Emplacement',b.location||'—'],['Autres éditions',editions.length]].map(([k,v])=>`<p><small>${k}</small>${esc(v)}</p>`).join('')}</div><p>${esc(b.review||'')}</p><div class="box section"><label class="field">Pages lues / ${esc(b.pages||'total non renseigné')}<input type="number" id="quick-progress" min="0" ${Number(b.pages)>0?'max="'+Number(b.pages)+'"':''} value="${Number(b.progress)||0}"></label><div class="actions"><button class="btn" data-save-progress="${esc(id)}">Mettre à jour</button><button class="btn" data-finish="${esc(id)}">Terminer</button></div>${readingProgress(b)}</div><div class="actions"><button class="btn primary" data-edit="${esc(id)}">Modifier la fiche</button><button class="btn" data-favorite="${esc(id)}">${b.favorite?'♥ Favori':'♡ Favori'}</button>${b.ownership==='wish'?`<button class="btn" data-acquire="${esc(id)}">Ajouter à ma collection</button>`:`<button class="btn" data-position="${esc(id)}">Déplacer dans le meuble</button>`}</div>${editions.length?'<h3>Autres éditions</h3>'+editions.map(x=>`<button class="btn" data-detail="${esc(x.id)}">${esc(x.title)} · ${esc(lang(x.language))} · ${esc(x.publisher)}</button>`).join(''):''}<div class="actions">${b.series?`<button class="btn" data-series="${esc(b.series)}">Ouvrir la série</button>`:''}${b.authors.split(',').map(s=>s.trim()).filter(Boolean).map(n=>`<button class="btn" data-author="${esc(n)}">${esc(n)}</button>`).join('')}</div>`)}
function seriesData(name){const books=ownedBooks().filter(b=>b.series===name),set=new Set(books.map(b=>Number(b.volume)).filter(n=>Number.isInteger(n)&&n>0)),total=Number(state.v2.seriesCatalog[name]?.total)||Math.max(0,...set),missing=[];for(let i=1;i<=Math.min(1000,total);i++)if(!set.has(i))missing.push(i);return {books,set,total,missing,known:Number(state.v2.seriesCatalog[name]?.total)>0}}
function seriesPage(){const a=ownedBooks(),names=[...new Set([...a.map(b=>b.series),...Object.keys(state.v2.seriesCatalog)].filter(Boolean))].sort(collator.compare),authors=[...new Set(a.flatMap(b=>b.authors.split(',').map(x=>x.trim()).filter(Boolean)))].sort(collator.compare);return `<div class="searchline"><input id="entity-search" placeholder="Rechercher série ou auteur…" aria-label="Rechercher série ou auteur"><button class="btn" data-action="entity-sort">↕</button></div><h2>Séries · ${names.length}</h2><div id="series-entities">${names.map(n=>{const s=seriesData(n),pct=s.total?Math.round(s.set.size/s.total*100):0;return `<button class="tile section entity" data-series="${esc(n)}" data-entity-name="${esc(norm(n))}"><b>${esc(n)}</b><small>${s.set.size} tome(s) / ${s.known?s.total:'total inconnu'} · ${s.books.length} édition(s)</small><div class="bar" style="width:100%"><span style="width:${Math.min(100,pct)}%"></span></div></button>`}).join('')||empty('Renseigne la série dans une fiche livre.')}</div><h2>Auteurs · ${authors.length}</h2><div id="author-entities">${authors.map(n=>`<button class="tile section entity" data-author="${esc(n)}" data-entity-name="${esc(norm(n))}"><b>${esc(n)}</b><small>${a.filter(b=>b.authors.split(',').map(x=>x.trim()).includes(n)).length} livre(s) possédé(s)</small></button>`).join('')||empty('Aucun auteur renseigné.')}</div>`}
function seriesDetail(n){const s=seriesData(n);modal(n,`<p>${s.set.size} tome(s) distinct(s) · ${s.books.length} édition(s) · total ${s.known?s.total:'non renseigné'}</p><div class="bar"><span style="width:${s.total?Math.min(100,s.set.size/s.total*100):0}%"></span></div><label class="field">Nombre total de tomes connus<input id="series-total" type="number" min="1" max="1000" value="${s.known?s.total:''}"></label><button class="btn" data-save-series="${esc(n)}">Enregistrer le total</button><h3 style="margin-top:20px">Tomes possédés</h3><div class="books">${s.books.slice().sort((a,b)=>collator.compare(a.volume,b.volume)).map(b=>`<div><small>Tome ${esc(b.volume||'non renseigné')} · ${esc(lang(b.language))}</small>${card(b)}</div>`).join('')||empty('Aucun tome possédé.')}</div><h3>Tomes manquants</h3><p>${s.missing.length?s.missing.map(i=>'Tome '+i).join(' · '):s.known?'Aucun numéro manquant détecté.':'Aucun trou dans les numéros possédés. Renseigne le total pour identifier les tomes suivants.'}</p><p class="note">Les éditions et langues différentes d’un même numéro comptent pour un seul tome. Les numéros non entiers restent visibles sans déduire de tome manquant.</p>`)}
function authorDetail(n){const a=ownedBooks().filter(b=>b.authors.split(',').map(x=>x.trim()).includes(n)),series=[...new Set(a.map(b=>b.series).filter(Boolean))];modal(n,`<p>${a.length} livre(s) possédé(s)</p><div class="actions">${series.map(s=>`<button class="btn" data-series="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="books section" style="margin-top:20px">${a.map(card).join('')}</div>`)}
function filtersModal(){const opts=(name,title,values,current)=>`<label class="field">${title}<select name="${name}"><option value="">Tous</option>${values.map(([v,l])=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;modal('Filtres avancés',`<form id="filters-form"><div class="fields" style="margin-top:20px">${opts('language','Langue',[['fr','Français'],['de','Allemand'],['en','Anglais'],['other','Autre']],filterLanguage)}${opts('genre','Genre',group(db.books,'genre').map(([v])=>[v,v]),filterGenre)}${opts('reading','Statut',['unread','reading','done','abandoned'].map(v=>[v,status(v)]),filterStatus)}${opts('kind','Type',group(db.books,'kind').map(([v])=>[v,v]),filterKind)}${opts('format','Support',group(db.books,'format').map(([v])=>[v,v]),filterFormat)}${opts('series','Série',group(db.books.filter(b=>b.series),'series').map(([v])=>[v,v]),filterSeries)}${opts('rating','Note minimum',[1,2,3,4,5].map(v=>[String(v),v+' ★']),filterRating)}${opts('favorite','Favoris',[['yes','Favoris seulement']],state.literary.favoriteOnly?'yes':'')}</div><div class="actions"><button class="btn primary" type="submit">Appliquer</button><button class="btn" type="button" data-action="reset-filters">Tout effacer</button></div></form>`);$('#filters-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);filterLanguage=f.get('language');filterGenre=f.get('genre');filterStatus=f.get('reading');filterKind=f.get('kind');filterFormat=f.get('format');filterSeries=f.get('series');filterRating=f.get('rating');commit({...state,literary:{...state.literary,favoriteOnly:f.get('favorite')==='yes'}});persistUI();closeModal();render()}}
function settingsModal(){setPage('settings')}
function shelfLayout(){const l=structuredClone(state.literary.layout),a=ownedBooks(),ids=new Set(a.map(b=>b.id)),occupied=new Set();for(const [id,p] of Object.entries(l.positions)){if(!ids.has(id)||!p||!Number.isInteger(p.cabinet)||p.cabinet<0||p.cabinet>=1000||!Number.isInteger(p.shelf)||p.shelf<0||p.shelf>3||!Number.isInteger(p.slot)||p.slot<0||p.slot>7){delete l.positions[id];continue}const k=`${p.cabinet}:${p.shelf}:${p.slot}`;if(occupied.has(k))delete l.positions[id];else occupied.add(k)}let count=Math.max(l.cabinets,Math.ceil(a.length/32),...Object.values(l.positions).map(p=>p.cabinet+1));for(const b of a){if(l.positions[b.id])continue;let placed=false;for(let c=0;!placed;c++)for(let s=0;s<4&&!placed;s++)for(let k=0;k<8&&!placed;k++){const key=`${c}:${s}:${k}`;if(!occupied.has(key)){l.positions[b.id]={cabinet:c,shelf:s,slot:k};occupied.add(key);count=Math.max(count,c+1);placed=true}}}l.cabinets=count;return l}
function shelfPage(){const l=shelfLayout(),a=ownedBooks();if(JSON.stringify(l)!==JSON.stringify(state.literary.layout))saveLayout(l);const colors=['#3b251c','#47382a','#1e2926','#583126','#382d27','#453627','#563e25','#3e2920'];return `<div class="shelf-controls"><button class="btn" data-action="cabinet-settings">☼ Personnaliser</button><button class="btn" data-action="arrange">⇄ Ranger</button><button class="btn" data-action="new-cabinet">＋ Meuble</button></div><p class="note shelf-help">${a.length} livre(s) · ${l.cabinets} meuble(s). Touche une tranche pour ouvrir sa fiche.</p><div class="cabinet-grid">${Array.from({length:l.cabinets},(_,c)=>`<div><div class="cabinet ${l.finish} ${l.lights?'':'unlit'}" data-cabinet="${c}" aria-label="Meuble ${c+1}">${Array.from({length:4},(_,s)=>{const decor=l.decorations[c+':'+s];const books=a.filter(b=>l.positions[b.id]?.cabinet===c&&l.positions[b.id]?.shelf===s).sort((a,b)=>l.positions[a.id].slot-l.positions[b.id].slot);return `<div class="shelfrow ${decor?'decorated':''} ${decor&&l.decorSides[c+':'+s]==='left'?'decor-left':''}" data-shelf="${s}">${Array.from({length:8},(_,k)=>{const b=books.find(b=>l.positions[b.id].slot===k);if(!b)return `<span class="slotgap" style="flex:0 0 ${decor?'8':'10'}%;height:4px" data-slot="${k}"></span>`;let hash=[...b.title].reduce((n,x)=>n+x.charCodeAt(0),0);return `<button class="spine" draggable="true" data-spine="${esc(b.id)}" data-slot="${k}" aria-label="${esc(b.title)}, étagère ${s+1}, position ${k+1}" style="--sw:${decor?'8':'10'}%;--sh:${72+hash%22}%;--spine:${colors[hash%colors.length]}"><span>${esc(b.title)}</span><small>${esc(b.authors.split(',')[0])}</small></button>`}).join('')}${decor?`<div class="decoration deco-${esc(decor)}" role="img" aria-label="${esc(decor)}"></div>`:''}</div>`}).join('')}</div><p class="cabinet-caption">Meuble ${c+1} · ${a.filter(b=>l.positions[b.id]?.cabinet===c).length} livres</p></div>`).join('')}</div>${!a.length?empty('Le meuble est vide. Ajoute ou importe tes livres pour le remplir.'):''}`}
function bindShelf(){let dragged=null;$('#app').querySelectorAll('[data-spine]').forEach(e=>e.addEventListener('dragstart',ev=>{dragged=e.dataset.spine;ev.dataTransfer.setData('text/plain',dragged);ev.dataTransfer.effectAllowed='move'}));$('#app').querySelectorAll('.shelfrow').forEach(e=>{e.addEventListener('dragover',ev=>{ev.preventDefault();ev.dataTransfer.dropEffect='move'});e.addEventListener('drop',ev=>{ev.preventDefault();const id=dragged||ev.dataTransfer.getData('text/plain'),c=Number(e.closest('[data-cabinet]').dataset.cabinet),s=Number(e.dataset.shelf),slot=Number(ev.target.closest('[data-slot]')?.dataset.slot??0);moveBook(id,c,s,slot)})})}
function moveBook(id,c,s,k){const l=shelfLayout();if(!ownedBooks().some(b=>b.id===id))return;const old=l.positions[id];for(const [other,p] of Object.entries(l.positions))if(other!==id&&p.cabinet===c&&p.shelf===s&&p.slot===k)l.positions[other]=old;l.positions[id]={cabinet:c,shelf:s,slot:k};l.cabinets=Math.max(l.cabinets,c+1);l.auto=false;if(saveLayout(l)){closeModal();render();toast('Position enregistrée')}}
function positionModal(id){const l=shelfLayout(),p=l.positions[id]||{cabinet:0,shelf:0,slot:0};modal('Déplacer le livre',`<p>${esc(db.books.find(b=>b.id===id)?.title)}</p><form id="position-form"><label class="field">Meuble<select name="cabinet">${Array.from({length:l.cabinets+1},(_,i)=>`<option value="${i}" ${p.cabinet===i?'selected':''}>Meuble ${i+1}${i===l.cabinets?' (nouveau)':''}</option>`).join('')}</select></label><label class="field">Étagère<select name="shelf">${[0,1,2,3].map(i=>`<option value="${i}" ${p.shelf===i?'selected':''}>${i+1} · ${i===0?'haut':i===3?'bas':'milieu'}</option>`).join('')}</select></label><label class="field">Position de gauche à droite<select name="slot">${Array.from({length:8},(_,i)=>`<option value="${i}" ${p.slot===i?'selected':''}>${i+1}</option>`).join('')}</select></label><p class="note">Si la position est occupée, les deux livres échangent leur place.</p><button class="btn primary" type="submit">Enregistrer la position</button></form>`);$('#position-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);moveBook(id,Number(f.get('cabinet')),Number(f.get('shelf')),Number(f.get('slot')))}}
function arrangeModal(){modal('Rangement automatique',`<p>Réorganiser tous les livres remplace leurs positions manuelles. Les livres et les données de lecture sont conservés.</p><label class="field">Critère<select id="arrange-order"><option value="authors">Auteur, puis série et tome</option><option value="series">Série et tome</option><option value="genre">Genre</option><option value="title">Titre</option><option value="language">Langue</option></select></label><div class="actions"><button class="btn primary" data-action="confirm-arrange">Ranger maintenant</button><button class="btn" data-action="close">Annuler</button></div>`)}
function cabinetSettings(){const l=shelfLayout();modal('Personnaliser le meuble',`<form id="cabinet-form"><div class="fields" style="margin-top:20px"><label class="field">Finition<select name="finish">${[['walnut','Noyer foncé'],['oak','Chêne naturel'],['mahogany','Acajou']].map(([v,t])=>`<option value="${v}" ${l.finish===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Éclairage<select name="lights"><option value="on" ${l.lights?'selected':''}>Activé</option><option value="off" ${!l.lights?'selected':''}>Éteint</option></select></label></div><h3 style="margin-top:20px">Décorations · espaces réservés</h3><p class="note">Choisis l’étagère et le côté de chaque objet. La place est réservée pour ne masquer aucun livre.</p>${Array.from({length:l.cabinets},(_,c)=>`<h3>Meuble ${c+1}</h3><div class="fields">${[0,1,2,3].map(s=>`<label class="field">Étagère ${s+1}<select name="decor-${c}-${s}">${[['','Aucune'],['plant','Plante'],['globe','Globe terrestre'],['lantern','Lanterne'],['frame','Cadre']].map(([v,t])=>`<option value="${v}" ${l.decorations[c+':'+s]===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Côté · étagère ${s+1}<select name="side-${c}-${s}"><option value="right" ${l.decorSides[c+':'+s]!=='left'?'selected':''}>Droite</option><option value="left" ${l.decorSides[c+':'+s]==='left'?'selected':''}>Gauche</option></select></label>`).join('')}</div>`).join('')}<div class="actions"><button type="submit" class="btn primary">Enregistrer l’ambiance</button></div></form>`);$('#cabinet-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);l.finish=f.get('finish');l.lights=f.get('lights')==='on';for(let c=0;c<l.cabinets;c++)for(let s=0;s<4;s++){l.decorations[c+':'+s]=f.get(`decor-${c}-${s}`);l.decorSides[c+':'+s]=f.get(`side-${c}-${s}`);}if(saveLayout(l)){closeModal();render()}}}
function dataPage(){return `<div class="box section"><h2>Sauvegarde complète</h2><p class="note">Livres, éditions, séances, prêts, objectifs, séries, positions et personnalisation. Les couvertures enregistrées sous forme d’URL nécessitent Internet ou leur cache sur cet appareil.</p><div class="actions"><button class="btn primary" data-action="export-json">Exporter JSON</button><button class="btn" data-action="export-csv">Exporter CSV</button></div></div><div class="box section"><h2>Restaurer un JSON V1, V2 ou Literary</h2><p class="formnote">La restauration remplace l’ensemble des livres et du suivi. Aucune fusion. Le fichier sera contrôlé avant confirmation ; une sauvegarde de l’état actuel sera conservée localement et proposée au téléchargement.</p><input type="file" id="restore-file" accept="application/json,.json"><p id="restore-info" class="note"></p></div><div class="box section"><h2>Protection et récupération</h2><p class="note">Les données V1/V2 d’origine restent intactes dans leurs clés historiques. Literary utilise un enregistrement unique pour éviter une restauration partielle entre livres et suivi.</p><div class="actions"><button class="btn" data-action="raw-backup">Exporter les données brutes</button><button class="btn" data-action="rollback">Rétablir l’état avant restauration</button></div></div><div class="box section"><h2>Livres supprimés</h2><p class="note">${(state.literary.trash||[]).length} fiche(s) récupérable(s), dans la limite des 100 dernières suppressions.</p><button class="btn" data-action="restore-trash">Récupérer la dernière fiche supprimée</button></div><div class="box section"><h2>Effacement</h2><p class="note">Effacer Literary ne supprime pas les anciennes clés V1/V2.</p><button class="btn danger" data-action="clear-literary">Effacer la collection Literary</button></div>`}
let pendingRestore=null;
async function stageRestore(file){try{if(!file)return;if(file.size>25*1024*1024)throw Error('Fichier trop volumineux (25 Mo maximum)');pendingRestore=validateBackup(JSON.parse(await file.text()));modal('Vérifier la restauration',`<p><b>${pendingRestore.books.length} livres</b><br>${pendingRestore.v2.journal.length} séances · ${pendingRestore.v2.loans.length} prêts · objectif ${pendingRestore.v2.goal} livres.</p><p class="formnote">Cela remplacera les ${db.books.length} livres actuels, leur suivi et la disposition du meuble. Les sauvegardes V1/V2 sans disposition créent un meuble neuf. Aucun mélange avec la collection précédente.</p><div class="actions"><button class="btn" data-action="close">Annuler</button><button class="btn primary" data-action="restore-confirm">Sauvegarder et remplacer</button></div>`)}catch(e){pendingRestore=null;alert('Restauration refusée : '+e.message)}}
function restoreConfirmed(){if(!pendingRestore)return;try{localStorage.setItem('ma-bibliotheque-literary-before-restore',JSON.stringify(snapshot()));exportJSON('ma-bibliotheque-avant-restauration');const candidate=pendingRestore;if(storageBlocked){localStorage.setItem('ma-bibliotheque-literary-recovery-raw',localStorage.getItem(LKEY)||'');storageBlocked=false}if(commit(candidate)){pendingRestore=null;query=filterLanguage=filterGenre=filterStatus=filterKind=filterFormat=filterSeries=filterRating='';if(candidate.ui){const u=candidate.ui;viewMode=['list','grid'].includes(u.viewMode)?u.viewMode:'grid';sortMode=['recent','title','authors','published','rating','pages','progress'].includes(u.sortMode)?u.sortMode:'recent';sortDirection=u.sortDirection==='asc'?'asc':'desc';for(const k of ['query','filterLanguage','filterGenre','filterStatus','filterKind','filterFormat','filterSeries','filterRating'])if(typeof u[k]==='string')({query:v=>query=v,filterLanguage:v=>filterLanguage=v,filterGenre:v=>filterGenre=v,filterStatus:v=>filterStatus=v,filterKind:v=>filterKind=v,filterFormat:v=>filterFormat=v,filterSeries:v=>filterSeries=v,filterRating:v=>filterRating=v})[k](u[k])}persistUI();closeModal();render();toast('Restauration complète effectuée')}}catch(e){alert('Restauration interrompue : '+e.message)}}
function exportCSV(){const keys=Object.keys(blank()),rows=[keys,...db.books.map(b=>keys.map(k=>String(b[k]??'')))];download('\ufeff'+rows.map(r=>r.map(v=>{v=String(v);if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}).join(';')).join('\r\n'),'ma-bibliotheque-'+today()+'.csv','text/csv;charset=utf-8')}
function editGoal(){const y=new Date().getFullYear();modal('Objectif annuel',`<form id="goal-form"><label class="field">Année<input name="year" type="number" min="1900" max="2200" value="${y}" required></label><label class="field">Livres à terminer<input name="goal" type="number" min="1" max="10000" value="${state.v2.goals?.[y]||state.v2.goal}" required></label><div class="actions"><button class="btn primary">Enregistrer</button></div></form>`);$('#goal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),x=readV2(),year=Number(f.get('year')),g=Number(f.get('goal'));if(!Number.isInteger(g)||g<1||g>10000)return;x.goals={...x.goals,[year]:g};if(year===y)x.goal=g;if(saveV2(x)){closeModal();render()}}}
/* Reuse V2 session/loan editor with a page-aware render hook. */
renderV2=function(){render()};
function updateBook(id,patch){const b=db.books.find(b=>b.id===id);if(!b)return false;return saveCandidate({...db,books:db.books.map(b=>b.id===id?{...b,...patch}:b)})}
function chartDetail(key,value){let list=ownedBooks().filter(b=>key==='finishedMonth'?b.reading==='done'&&b.finished.startsWith(value):key==='finishedYear'?b.reading==='done'&&b.finished.startsWith(value):key==='growth'?(b.acquired||b.created).slice(0,7)<=value:key==='genre'?(b.genre||'Non renseigné').split(',').map(s=>s.trim()).includes(value):String(b[key]||'Non renseigné')===value);modal('Détail · '+(key==='reading'?status(value):key==='language'?lang(value):value),`<p>${list.length} livre(s)</p><div class="books">${list.map(card).join('')||empty('Aucun livre.')}</div>`)}
let swStatus=('serviceWorker' in navigator&&window.isSecureContext)?'Hors ligne : vérification en cours':'Mode hors ligne non testable sur cette origine HTTP ; HTTPS requis';
function handleClick(e){const el=e.target.closest('button,[data-detail]');if(!el)return;const d=el.dataset;
 if(d.detail){detail(d.detail);return}if(d.spine){el.classList.add('selected');setTimeout(()=>detail(d.spine),220);return}if(d.edit){form(db.books.find(b=>b.id===d.edit));return}if(d.author){authorDetail(d.author);return}if(d.series){seriesDetail(d.series);return}if(d.chartKey){chartDetail(d.chartKey,d.chartValue);return}
 if(d.saveSeries){const n=Number($('#series-total').value);if(!Number.isInteger(n)||n<1||n>1000){toast('Indique un total entier entre 1 et 1000');return}const x=readV2();x.seriesCatalog={...x.seriesCatalog,[d.saveSeries]:{...x.seriesCatalog[d.saveSeries],total:n}};if(saveV2(x)){render();seriesDetail(d.saveSeries)}return}
 if(d.position){positionModal(d.position);return}if(d.favorite){const b=db.books.find(b=>b.id===d.favorite);if(updateBook(b.id,{favorite:!b.favorite})){render();detail(b.id)}return}
 if(d.acquire){if(updateBook(d.acquire,{ownership:'owned',acquired:today()})){render();detail(d.acquire)}return}
 if(d.saveProgress){const b=db.books.find(b=>b.id===d.saveProgress),n=Number($('#quick-progress').value);if(!Number.isInteger(n)||n<0||(Number(b.pages)>0&&n>Number(b.pages))){toast('Nombre de pages invalide');return}if(updateBook(b.id,{progress:n,reading:b.reading==='done'?'done':'reading',started:b.started||today()})){render();detail(b.id)}return}
 if(d.finish){if(updateBook(d.finish,{reading:'done',finished:today(),progress:Number(db.books.find(b=>b.id===d.finish).pages)||0})){render();detail(d.finish)}return}
 if(d.delSession){if(confirm('Supprimer cette séance ?')){const x=readV2();x.journal=x.journal.filter(v=>v.id!==d.delSession);if(saveV2(x))render()}return}
 if(d.loanReturn||d.loanDelete){const x=readV2();if(d.loanReturn){const l=x.loans.find(l=>l.id===d.loanReturn);l.returned=!l.returned;l.returnedAt=l.returned?today():''}else{if(!confirm('Supprimer ce prêt ?'))return;x.loans=x.loans.filter(l=>l.id!==d.loanDelete)}if(saveV2(x))render();return}
 if(d.location){const a=ownedBooks().filter(b=>(b.location||'Non renseigné')===d.location);modal(d.location,`<div class="books" style="margin-top:20px">${a.map(card).join('')}</div>`);return}
 const action=d.action;if(!action)return;
 if(action==='close'){closeModal();return}if(action==='add')form();if(action==='filters')filtersModal();if(action==='goal')editGoal();if(action==='session')v2Modal('journal');if(action==='loan')v2Modal('loan');if(action==='export-json')exportJSON();if(action==='export-csv')exportCSV();if(action==='restore-confirm')restoreConfirmed();
 if(action==='view'){viewMode=viewMode==='grid'?'list':'grid';persistUI();render()}
 if(action==='direction'){sortDirection=sortDirection==='desc'?'asc':'desc';persistUI();render()}
 if(action==='reset-filters'){query=filterLanguage=filterGenre=filterStatus=filterKind=filterFormat=filterSeries=filterRating='';commit({...state,literary:{...state.literary,favoriteOnly:false}});persistUI();closeModal();render()}
 if(action==='cabinet-settings')cabinetSettings();if(action==='arrange')arrangeModal();
 if(action==='new-cabinet'){const l=shelfLayout();l.cabinets++;if(saveLayout(l))render()}
 if(action==='confirm-arrange'){const order=$('#arrange-order').value,l=shelfLayout(),a=ownedBooks().slice().sort((x,y)=>collator.compare(x[order],y[order])||collator.compare(x.series,y.series)||collator.compare(x.volume,y.volume)||collator.compare(x.title,y.title));l.positions={};a.forEach((b,i)=>l.positions[b.id]={cabinet:Math.floor(i/32),shelf:Math.floor(i%32/8),slot:i%8});l.auto=false;l.order=order;if(saveLayout(l)){closeModal();render();toast('Livres rangés')}}
 if(action==='raw-backup'){const keys=[KEY,V2KEY,UIKEY,THEME,LKEY,'ma-bibliotheque-pre-literary-backup'];download(JSON.stringify(Object.fromEntries(keys.map(k=>[k,localStorage.getItem(k)])),null,2),'bibliotheque-donnees-brutes-'+today()+'.json','application/json')}
 if(action==='rollback'){try{const raw=localStorage.getItem('ma-bibliotheque-literary-before-restore');if(!raw){toast('Aucun état avant restauration');return}pendingRestore=validateBackup(JSON.parse(raw));modal('Rétablir la sauvegarde locale',`<p>${pendingRestore.books.length} livres. Cette action remplacera l’état actuel.</p><button class="btn primary" data-action="restore-confirm">Sauvegarder et remplacer</button>`)}catch(err){alert(err.message)}}
 if(action==='clear-literary'){if(confirm('Effacer TOUS les livres, suivis et positions de Literary ? Une sauvegarde sera téléchargée.'))if(confirm('Confirmer cet effacement ?')){exportJSON('bibliotheque-avant-effacement');if(commit({version:3,books:[],v2:extrasDefault(),literary:{theme:state.literary.theme,layout:layoutDefault()}}))render()}}
 if(action==='restore-trash'){const trash=[...(state.literary.trash||[])],last=trash.pop();if(!last){toast('Aucune fiche à récupérer');return}if(db.books.some(b=>b.id===last.book.id)){toast('Cette fiche existe déjà');return}if(commit({...state,books:[...db.books,last.book],literary:{...state.literary,trash}})){render();toast('Fiche récupérée')}}
 if(action==='entity-sort'){for(const id of ['series-entities','author-entities']){const node=$('#'+id);[...node.children].reverse().forEach(x=>node.append(x))}}
}
$('#app').addEventListener('click',handleClick);$('#overlay').addEventListener('click',handleClick);
$('#overlay').addEventListener('click',e=>{if(e.target.classList.contains('modalwrap'))closeModal()});
$('#app').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-detail]')){e.preventDefault();detail(e.target.dataset.detail)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay .modal')){const items=[...$('#overlay .modal').querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}});
$('#app').addEventListener('input',e=>{if(e.target.id==='literary-search'){query=e.target.value;persistUI();paintResults()}if(e.target.id==='entity-search'){const q=norm(e.target.value);document.querySelectorAll('[data-entity-name]').forEach(x=>x.classList.toggle('hide',!x.dataset.entityName.includes(q)))}});
$('#app').addEventListener('change',e=>{if(e.target.id==='literary-sort'){sortMode=e.target.value;persistUI();paintResults()}if(e.target.id==='theme-select'){if(commit({...state,literary:{...state.literary,theme:e.target.value}}))applyTheme()}if(e.target.id==='restore-file')stageRestore(e.target.files[0])});
window.addEventListener('online',()=>{toast('Connexion rétablie');if(page==='settings')render()});window.addEventListener('offline',()=>{toast('Mode hors connexion');if(page==='settings')render()});
applyTheme();try{page=sessionStorage.getItem('literary-page')||'home'}catch{}render();
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async r=>{await r.update();await navigator.serviceWorker.ready;const cache=await caches.open('ma-bibliotheque-literary-20261103-r1'),shell=await cache.match(new URL('./index.html',location.href));swStatus=shell?'Application disponible hors ligne':'Cache non vérifié';if(page==='settings')render();r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Mise à jour disponible au prochain lancement')})})}).catch(e=>{swStatus='Mode hors ligne indisponible : '+e.message;if(page==='settings')render()})}

function catalogFetch(url){return fetch(url,{signal:AbortSignal.timeout(12000)})}
